public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            // Check if this is the last character, in which case it's an invalid escape
            if (i == length - 1) {
                throw new Exception("Invalid escape character at end of string");
            }
            char nextChar = str.charAt(++i);
            switch (nextChar) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u':
                    // Handle Unicode escape
                    if (i + 4 >= length) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        output.append((char) value);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: " + hex);
                    }
                    i += 4; // Move past the hex digits
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}
